  }
}

resource "google_sql_database_instance" "example" {
  name = "mydb"

  settings {
    ip_configuration {
      ipv4_enabled = false

      authorized_networks {
        name  = "any"
        value = "0.0.0.0/0"
      }
    }
  }
}

resource "google_compute_firewall" "example" {
  name    = "allow-all"
  network = "default"

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = ["0.0.0.0/0"]
}

resource "google_sql_database_instance" "example" {
  name = "mydb"

  settings {
    ip_configuration {
      ipv4_enabled = false

      authorized_networks {
        name  = "office"
        value = "203.0.113.0/24"
      }
    }
  }
}

resource "google_compute_firewall" "example" {
  name    = "allow-internal"
  network = "default"

  allow {
    protocol = "tcp"
    ports    = ["443"]
  }

  source_ranges = ["10.0.0.0/8"]
}

resource "google_compute_firewall" "example" {
  name      = "deny-egress"
  network   = "default"
  direction = "EGRESS"

  deny {
    protocol = "all"
  }

  destination_ranges = ["0.0.0.0/0"]
}
